/* eslint-disable max-statements, max-lines-per-function */

'use strict';

// MODULES //

var objectKeys = require( '@stdlib/utils/keys' );
var format = require( '@stdlib/string/format' );
var resolveSchemaValues = require( './resolve_schema_values.js' );
var defaults = require( './../defaults.js' );


// VARIABLES //

var EMPTY_STRING = [ '' ];


// MAIN //

/**
* Adds an axis menu to a parent folder.
*
* @private
* @param {Editor} parent - parent folder instance
* @param {Object} conf - editor axis configuration
* @param {Object} schema - visualization schema
* @param {string} name - folder name
* @returns {(Object|null)} menu tree
*/
function addMenu( parent, conf, schema, name ) {
	var controllers;
	var controller;
	var folder;
	var keys;
	var def;
	var d;
	var i;
	var k;

	keys = objectKeys( conf );
	if ( keys.length === 0 ) {
		return null;
	}
	folder = parent.addFolder( name );
	folder.close();

	def = defaults.axis;

	controllers = {};
	for ( i = 0; i < keys.length; i++ ) {
		k = keys[ i ];
		d = def[ k ];
		if ( k === 'aria' ) {
			controller = folder.add( conf, k );
		} else if ( k === 'bandPosition' ) {
			controller = folder.add( conf, k );
		} else if ( k === 'description' ) {
			controller = folder.add( conf, k );
		} else if ( k === 'domain' ) {
			controller = folder.add( conf, k );
		} else if ( k === 'domainCap' ) {
			controller = folder.add( conf, k, EMPTY_STRING.concat( d.values ) );
		} else if ( k === 'domainColor' ) {
			controller = folder.addColor( conf, k );
		} else if ( k === 'domainDash' ) {
			controller = folder.add( conf, k );
		} else if ( k === 'domainDashOffset' ) {
			controller = folder.add( conf, k );
			controller.name( format( '%s (%s)', k, d.units ) );
		} else if ( k === 'domainOpacity' ) {
			controller = folder.add( conf, k )
				.min( d.min )
				.max( d.max );
		} else if ( k === 'domainWidth' ) {
			controller = folder.add( conf, k )
				.min( d.min );
			controller.name( format( '%s (%s)', k, d.units ) );
		} else if ( k === 'grid' ) {
			controller = folder.add( conf, k );
		} else if ( k === 'gridCap' ) {
			controller = folder.add( conf, k, EMPTY_STRING.concat( d.values ) );
		} else if ( k === 'gridColor' ) {
			controller = folder.addColor( conf, k );
		} else if ( k === 'gridDash' ) {
			controller = folder.add( conf, k );
		} else if ( k === 'gridDashOffset' ) {
			controller = folder.add( conf, k );
			controller.name( format( '%s (%s)', k, d.units ) );
		} else if ( k === 'gridOpacity' ) {
			controller = folder.add( conf, k )
				.min( d.min )
				.max( d.max );
		} else if ( k === 'gridScale' ) {
			controller = folder.add( conf, k, resolveSchemaValues( schema, 'scales.*.name' ) ).disable();
		} else if ( k === 'gridWidth' ) {
			controller = folder.add( conf, k )
				.min( d.min );
			controller.name( format( '%s (%s)', k, d.units ) );
		} else if ( k === 'labelAlign' ) {
			controller = folder.add( conf, k, EMPTY_STRING.concat( d.values ) );
		} else if ( k === 'labelAngle' ) {
			controller = folder.add( conf, k )
				.min( d.min )
				.max( d.max );
			controller.name( format( '%s (%s)', k, d.units ) );
		} else if ( k === 'labelBaseline' ) {
			controller = folder.add( conf, k, EMPTY_STRING.concat( d.values ) );
		} else if ( k === 'labelBound' ) {
			controller = folder.add( conf, k );
		} else if ( k === 'labelColor' ) {
			controller = folder.addColor( conf, k );
		} else if ( k === 'labelFlush' ) {
			controller = folder.add( conf, k );
		} else if ( k === 'labelFlushOffset' ) {
			controller = folder.add( conf, k );
			controller.name( format( '%s (%s)', k, d.units ) );
		} else if ( k === 'labelFont' ) {
			controller = folder.add( conf, k );
		} else if ( k === 'labelFontSize' ) {
			controller = folder.add( conf, k )
				.min( d.min )
				.step( d.step );
			controller.name( format( '%s (%s)', k, d.units ) );
		} else if ( k === 'labelFontStyle' ) {
			controller = folder.add( conf, k, EMPTY_STRING.concat( d.values ) );
		} else if ( k === 'labelFontWeight' ) {
			controller = folder.add( conf, k, EMPTY_STRING.concat( d.values ) );
		} else if ( k === 'labelLimit' ) {
			controller = folder.add( conf, k )
				.min( d.min )
				.step( d.step );
			controller.name( format( '%s (%s)', k, d.units ) );
		} else if ( k === 'labelLineHeight' ) {
			controller = folder.add( conf, k )
				.min( d.min );
		} else if ( k === 'labelOffset' ) {
			controller = folder.add( conf, k );
			controller.name( format( '%s (%s)', k, d.units ) );
		} else if ( k === 'labelOpacity' ) {
			controller = folder.add( conf, k )
				.min( d.min )
				.max( d.max );
		} else if ( k === 'labelOverlap' ) {
			controller = folder.add( conf, k, EMPTY_STRING.concat( d.values ) );
		} else if ( k === 'labelPadding' ) {
			controller = folder.add( conf, k );
			controller.name( format( '%s (%s)', k, d.units ) );
		} else if ( k === 'labels' ) {
			controller = folder.add( conf, k );
		} else if ( k === 'labelSeparation' ) {
			controller = folder.add( conf, k )
				.min( d.min )
				.step( d.step );
		} else if ( k === 'maxExtent' ) {
			controller = folder.add( conf, k )
				.min( d.min );
			controller.name( format( '%s (%s)', k, d.units ) );
		} else if ( k === 'minExtent' ) {
			controller = folder.add( conf, k )
				.min( d.min );
			controller.name( format( '%s (%s)', k, d.units ) );
		} else if ( k === 'offset' ) {
			controller = folder.add( conf, k );
			controller.name( format( '%s (%s)', k, d.units ) );
		} else if ( k === 'orient' ) {
			controller = folder.add( conf, k, EMPTY_STRING.concat( d.values ) );
		} else if ( k === 'position' ) {
			controller = folder.add( conf, k );
			controller.name( format( '%s (%s)', k, d.units ) );
		} else if ( k === 'scale' ) {
			controller = folder.add( conf, k, resolveSchemaValues( schema, 'scales.*.name' ) );
		} else if ( k === 'tickBand' ) {
			controller = folder.add( conf, k, EMPTY_STRING.concat( d.values ) );
		} else if ( k === 'tickCap' ) {
			controller = folder.add( conf, k, EMPTY_STRING.concat( d.values ) );
		} else if ( k === 'tickColor' ) {
			controller = folder.addColor( conf, k );
		} else if ( k === 'tickCount' ) {
			controller = folder.add( conf, k );
		} else if ( k === 'tickDash' ) {
			controller = folder.add( conf, k );
		} else if ( k === 'tickDashOffset' ) {
			controller = folder.add( conf, k );
			controller.name( format( '%s (%s)', k, d.units ) );
		} else if ( k === 'tickMinStep' ) {
			controller = folder.add( conf, k )
				.min( d.min );
		} else if ( k === 'tickOffset' ) {
			controller = folder.add( conf, k )
				.min( d.min );
			controller.name( format( '%s (%s)', k, d.units ) );
		} else if ( k === 'tickOpacity' ) {
			controller = folder.add( conf, k )
				.min( d.min )
				.max( d.max );
		} else if ( k === 'ticks' ) {
			controller = folder.add( conf, k );
		} else if ( k === 'tickSize' ) {
			controller = folder.add( conf, k )
				.min( d.min );
			controller.name( format( '%s (%s)', k, d.units ) );
		} else if ( k === 'tickWidth' ) {
			controller = folder.add( conf, k )
				.min( d.min );
			controller.name( format( '%s (%s)', k, d.units ) );
		} else if ( k === 'title' ) {
			controller = folder.add( conf, k );
		} else if ( k === 'titleAlign' ) {
			controller = folder.add( conf, k, EMPTY_STRING.concat( d.values ) );
		} else if ( k === 'titleAnchor' ) {
			controller = folder.add( conf, k, EMPTY_STRING.concat( d.values ) );
		} else if ( k === 'titleAngle' ) {
			controller = folder.add( conf, k )
				.min( d.min )
				.max( d.max );
			controller.name( format( '%s (%s)', k, d.units ) );
		} else if ( k === 'titleBaseline' ) {
			controller = folder.add( conf, k, EMPTY_STRING.concat( d.values ) );
		} else if ( k === 'titleColor' ) {
			controller = folder.addColor( conf, k );
		} else if ( k === 'titleFont' ) {
			controller = folder.add( conf, k );
		} else if ( k === 'titleFontSize' ) {
			controller = folder.add( conf, k )
				.min( d.min )
				.step( d.step );
			controller.name( format( '%s (%s)', k, d.units ) );
		} else if ( k === 'titleFontStyle' ) {
			controller = folder.add( conf, k, EMPTY_STRING.concat( d.values ) );
		} else if ( k === 'titleFontWeight' ) {
			controller = folder.add( conf, k, EMPTY_STRING.concat( d.values ) );
		} else if ( k === 'titleLimit' ) {
			controller = folder.add( conf, k )
				.min( d.min )
				.step( d.step );
			controller.name( format( '%s (%s)', k, d.units ) );
		} else if ( k === 'titleLineHeight' ) {
			controller = folder.add( conf, k )
				.min( d.min );
		} else if ( k === 'titleOpacity' ) {
			controller = folder.add( conf, k )
				.min( d.min )
				.max( d.max );
		} else if ( k === 'titlePadding' ) {
			controller = folder.add( conf, k );
			controller.name( format( '%s (%s)', k, d.units ) );
		} else if ( k === 'titleX' ) {
			controller = folder.add( conf, k );
			controller.name( format( '%s (%s)', k, d.units ) );
		} else if ( k === 'titleY' ) {
			controller = folder.add( conf, k );
			controller.name( format( '%s (%s)', k, d.units ) );
		} else if ( k === 'zindex' ) {
			controller = folder.add( conf, k );
		} else {
			console.log( 'Unrecognized property in editor configuration. Key: %s.', k );
			continue;
		}
		controllers[ k ] = controller;
	}
	return {
		'folder': folder,
		'controllers': controllers
	};
}


// EXPORTS //

module.exports = addMenu;
